#include <gtest/gtest.h>

#include "bench/regression.hpp"

TEST(JudgeExpectation, RefusesAFailureOnADifferentCheck) {
  const bench::Expectation expected{
      .name = "normal without the relay", .passes = false, .failing = "goals reached in order"};
  const std::string_view verdict = "fail\nscenario: normal\nsamples: 790\n"
                                   "failed top speed: 0.40 m/s, at most 0.30 m/s\n";
  EXPECT_EQ(bench::judge_expectation(expected, verdict), bench::Outcome::wrong_check);
}

#include <algorithm>
#include <array>
#include <cstdint>
#include <format>
#include <iostream>
#include <ranges>
#include <span>
#include <string>
#include <string_view>
#include <vector>

namespace bench {

// bench/regression.hpp: what one regression case expects of a verdict file, and whether it got it.

struct Expectation {
  std::string name;     // what the case is called in the report
  bool passes;          // whether the scenario is supposed to pass
  std::string failing;  // the check that has to be the failed one; empty when the run should pass
};

enum class Outcome { met, wrong_verdict, wrong_check, unreadable };

[[nodiscard]] std::string_view describe(Outcome outcome) {
  switch (outcome) {
    case Outcome::met: return "as expected";
    case Outcome::wrong_verdict: return "the verdict came out the other way round";
    case Outcome::wrong_check: return "it failed, on a different check";
    case Outcome::unreadable: return "no verdict file to read";
  }
  return "?";
}

// The verdict file's first line is "pass" or "fail", and each check's line starts with "ok" or
// "failed" and then names the check. Nothing here reads a file: the caller passes the text in.
[[nodiscard]] Outcome judge_expectation(const Expectation& expected, std::string_view verdict) {
  std::vector<std::string_view> lines;
  for (const auto part : std::views::split(verdict, '\n')) {
    const std::string_view line(part.begin(), part.end());
    if (!line.empty()) lines.push_back(line);
  }
  if (lines.empty()) return Outcome::unreadable;
  if (lines.front() != "pass" && lines.front() != "fail") return Outcome::unreadable;
  if ((lines.front() == "pass") != expected.passes) return Outcome::wrong_verdict;
  if (expected.failing.empty()) return Outcome::met;

  const auto named = std::ranges::find_if(lines, [&expected](std::string_view line) {
    return line.starts_with("failed") && line.find(expected.failing) != std::string_view::npos;
  });
  return named == lines.end() ? Outcome::wrong_check : Outcome::met;
}

// One line for the suite's report, which is what the tool prints and the script collects.
[[nodiscard]] std::string report_line(const Expectation& expected, Outcome outcome) {
  return std::format("{:<7} {}: {}\n", outcome == Outcome::met ? "ok" : "failed", expected.name,
                     describe(outcome));
}

}  // namespace bench

int main() {
  // Four verdict files, as the runner writes them.
  constexpr std::string_view passed =
      "pass\nscenario: normal\nsamples: 812\n"
      "ok     goals reached in order: 2.00, at least 2.00\n"
      "ok     distance from the last goal at the end: 0.05 m, at most 0.10 m\n";
  constexpr std::string_view no_relay =
      "fail\nscenario: normal\nsamples: 790\n"
      "failed goals reached in order: 0.00, at least 2.00\n"
      "ok     top speed: 0.00 m/s, at most 0.30 m/s\n";
  constexpr std::string_view slow =
      "fail\nscenario: normal\nsamples: 815\n"
      "ok     goals reached in order: 2.00, at least 2.00\n"
      "failed time from the first movement to the last goal: 21.30 s, at most 20.00 s\n";
  constexpr std::string_view nothing;

  const std::array<bench::Expectation, 4> cases{{{.name = "normal", .passes = true, .failing = ""},
                                                 {.name = "normal without the relay",
                                                  .passes = false,
                                                  .failing = "goals reached in order"},
                                                 {.name = "normal, checked against a slow run",
                                                  .passes = false,
                                                  .failing = "goals reached in order"},
                                                 {.name = "missing_odom", .passes = true, .failing = ""}}};
  const std::array<std::string_view, 4> verdicts{passed, no_relay, slow, nothing};

  std::int64_t met = 0;
  for (std::int64_t i = 0; i < std::ssize(cases); ++i) {
    const auto k = static_cast<std::size_t>(i);
    const bench::Outcome outcome = bench::judge_expectation(cases[k], verdicts[k]);
    if (outcome == bench::Outcome::met) ++met;
    std::cout << bench::report_line(cases[k], outcome);
  }
  std::cout << std::format("{} of {} cases met their expectation\n", met, std::ssize(cases));
}

// check_verdict NAME pass|fail FAILING_CHECK VERDICT_FILE. Exit 0 when the case met its expectation.
int main(int argc, char** argv) {
  if (argc != 5) { std::cerr << "usage: check_verdict NAME pass|fail FAILING_CHECK VERDICT_FILE\n"; return 2; }
  const bench::Expectation expected{
      .name = argv[1], .passes = std::string_view(argv[2]) == "pass", .failing = argv[3]};
  std::ifstream in(argv[4]);
  std::ostringstream text;
  text << in.rdbuf();
  const bench::Outcome outcome = bench::judge_expectation(expected, text.str());
  std::cout << bench::report_line(expected, outcome);
  return outcome == bench::Outcome::met ? 0 : 1;
}

// In ScenarioRunner: which set of checks to apply, defaulting to the scenario's own name, so a
// variant of a scenario is judged by the checks of the scenario it varies.
checks_ = declare_parameter<std::string>("checks", scenario_);
// Every `scenario_ == "missing_odom"` in on_tick() and finish() becomes checks_ == "missing_odom".
